SELECT commit.collection AS event, count() AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT commit.collection AS event, count() AS count, uniqExact(did) AS users FROM bluesky WHERE kind = 'commit' AND commit.operation = 'create' GROUP BY event ORDER BY count DESC;
SELECT commit.collection AS event, toHour(fromUnixTimestamp64Micro(time_us)) as hour_of_day, count() AS count FROM bluesky WHERE kind = 'commit' AND commit.operation = 'create' AND commit.collection::String in ['app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like'] GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT did::String as user_id, min(fromUnixTimestamp64Micro(time_us)) as first_post_ts FROM bluesky WHERE kind = 'commit' AND commit.operation = 'create' AND commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT did::String as user_id, date_diff( 'milliseconds', min(fromUnixTimestamp64Micro(time_us)), max(fromUnixTimestamp64Micro(time_us))) AS activity_span FROM bluesky WHERE kind = 'commit' AND commit.operation = 'create' AND commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
